//! Private, offline, text-reflow EPUB2/3 profile. No extraction, scripts or webview.
use crate::{Result,epub_xml::{self as xml,Event}};
use serde_json::{json,Value};
use std::{collections::{BTreeMap,BTreeSet},io::{Read,Seek},fs::File,path::Path};
use zip::ZipArchive;
#[cfg(test)]use std::io::Cursor;
const ZIP_MAX:u64=1024*1024*1024;
#[derive(Clone)]struct Chapter{path:String,title:String}
struct Book<R:Read+Seek=File>{zip:ZipArchive<R>,chapters:Vec<Chapter>,toc:Vec<Value>,title:String,author:String,revision:String}
fn path(base:&str,href:&str)->Result<(String,String)>{
 if href.len()>1024||href.contains(['\\','?',':'])||href.chars().any(char::is_control)||href.starts_with('/'){return Err("Unsupported EPUB reference".into())}
 let (raw,fragment)=href.split_once('#').unwrap_or((href,""));
 fn unescape(s:&str)->Result<String>{let b=s.as_bytes();let mut out=Vec::new();let mut i=0;while i<b.len(){if b[i]==b'%'{if i+2>=b.len(){return Err("Invalid EPUB URL escape".into())}let pair=std::str::from_utf8(&b[i+1..i+3]).map_err(|_|"Invalid EPUB URL")?;out.push(u8::from_str_radix(pair,16).map_err(|_|"Invalid EPUB URL")?);i+=3}else{out.push(b[i]);i+=1}}String::from_utf8(out).map_err(|_|"Use UTF-8 EPUB URLs".into())}
 let decoded=unescape(raw)?;let fragment=unescape(fragment)?;if decoded.contains(['\\',':','\0'])||decoded.starts_with('/')||fragment.len()>256{return Err("Unsafe EPUB reference".into())}
 let mut parts:Vec<&str>=if raw.is_empty(){base.split('/').collect()}else{base.rsplit_once('/').map(|(d,_)|d.split('/').collect()).unwrap_or_default()};
 if !raw.is_empty(){for p in decoded.split('/'){match p{""|"."=>{},".."=>{parts.pop().ok_or("EPUB reference escapes archive")?;},_=>parts.push(p)}}}
 if parts.is_empty(){return Err("Empty EPUB reference".into())}Ok((parts.join("/"),fragment))
}
fn archive_name(s:&str)->bool{!s.is_empty()&&s.len()<=512&&!s.starts_with('/')&&!s.contains(['\\',':','\0'])&&s.trim_end_matches('/').split('/').all(|p|!p.is_empty()&&p!="."&&p!="..")}
fn read<R:Read+Seek>(zip:&mut ZipArchive<R>,name:&str)->Result<String>{let mut f=zip.by_name(name).map_err(|_|"Missing EPUB resource")?;if f.size()>1_048_576{return Err("EPUB XML/chapter exceeds1MiB".into())}let expected=f.size();let mut bytes=Vec::new();f.by_ref().take(1_048_577).read_to_end(&mut bytes).map_err(|_|"EPUB resource could not be decoded")?;if bytes.len() as u64!=expected{return Err("EPUB resource size changed".into())}String::from_utf8(bytes).map_err(|_|"Use UTF-8 EPUB content".into())}
fn text_between(events:&[Event],wanted:&str)->String{let mut capture:usize=0;let mut result=String::new();for e in events{match e{Event::Open(n,_)if xml::local(n)==wanted=>capture+=1,Event::Close(n)if xml::local(n)==wanted=>capture=capture.saturating_sub(1),Event::Text(t)if capture>0=>result.push_str(t),_=>{}}}result.trim().chars().take(256).collect()}
impl Book<File>{
 fn open(root:&Path,id:&str)->Result<Self>{let info=crate::sdk_storage::resolve(root,id)?;if info["size"].as_u64().unwrap_or(u64::MAX)>ZIP_MAX{return Err("Book exceeds the1GiB library file limit".into())}let file=File::open(info["path"].as_str().ok_or("Missing private book path")?).map_err(|_|"Could not open saved book")?;Self::reader(file,info["sha256"].as_str().unwrap_or("").into())}
}
#[cfg(test)]impl Book<Cursor<Vec<u8>>>{fn bytes(bytes:Vec<u8>,revision:String)->Result<Self>{Self::reader(Cursor::new(bytes),revision)}}
impl<R:Read+Seek> Book<R>{
 fn reader(reader:R,revision:String)->Result<Self>{
  let mut zip=ZipArchive::new(reader).map_err(|_|"This file is not a supported EPUB archive")?;if zip.len()>1024{return Err("EPUB entry limit reached".into())}
  let mut seen=BTreeSet::new();let mut total=0u64;for i in 0..zip.len(){let f=zip.by_index(i).map_err(|_|"Encrypted/invalid EPUB entry")?;let name=std::str::from_utf8(f.name_raw()).map_err(|_|"Use UTF-8 EPUB paths")?;if !archive_name(name)||!seen.insert(name.to_string())||f.unix_mode().is_some_and(|m|m&0o170000==0o120000){return Err("Duplicate or unsafe EPUB entry".into())}total=total.checked_add(f.size()).ok_or("EPUB size overflow")?;if total>2*ZIP_MAX||f.size()>128*1024*1024{return Err("EPUB decompression limit reached".into())}}
  {let f=zip.by_index(0).map_err(|_|"Missing EPUB mimetype")?;if f.name()!="mimetype"||f.compression()!=zip::CompressionMethod::Stored{return Err("EPUB mimetype must be the first uncompressed entry".into())}}
  if read(&mut zip,"mimetype")?!="application/epub+zip"{return Err("This file is not an EPUB publication".into())}
  if seen.contains("META-INF/encryption.xml"){return Err("Encrypted/DRM and obfuscated-font EPUBs are unsupported".into())}
  let container=xml::parse(&read(&mut zip,"META-INF/container.xml")?)?;let package=container.iter().find_map(|e|match e{Event::Open(n,a)if xml::local(n)=="rootfile"=>xml::attr(a,"full-path"),_=>None}).ok_or("Missing EPUB rootfile")?.to_string();if !archive_name(&package){return Err("Invalid EPUB package path".into())}
  let opf=xml::parse(&read(&mut zip,&package)?)?;let title=text_between(&opf,"title");let author=text_between(&opf,"creator");let mut manifest=BTreeMap::new();let mut refs=Vec::new();let mut version=String::new();let mut ncx=None;
  for e in &opf{if let Event::Open(n,a)=e{match xml::local(n){"package"=>version=xml::attr(a,"version").unwrap_or("").to_owned(),"item"=>{let id=xml::attr(a,"id").ok_or("Missing EPUB item ID")?;let href=xml::attr(a,"href").ok_or("Missing EPUB href")?;let mime=xml::attr(a,"media-type").ok_or("Missing EPUB media type")?;let props=xml::attr(a,"properties").unwrap_or("");if manifest.len()>=512||manifest.insert(id.to_string(),(path(&package,href)?.0,mime.to_string(),props.to_string())).is_some(){return Err("Duplicate or oversized EPUB manifest".into())}},"spine"=>ncx=xml::attr(a,"toc").map(str::to_owned),"itemref"=>{if xml::attr(a,"properties").unwrap_or("").contains("pre-paginated"){return Err("Fixed-layout EPUB is unsupported".into())}refs.push(xml::attr(a,"idref").ok_or("Missing EPUB spine reference")?.to_string());},_=>{}}}}
  for (i,e)in opf.iter().enumerate(){if let Event::Open(n,a)=e{if xml::local(n)=="meta"&&xml::attr(a,"property")==Some("rendition:layout")&&matches!(opf.get(i+1),Some(Event::Text(t)) if t.trim()=="pre-paginated"){return Err("Fixed-layout EPUB is unsupported".into())}}}
  if !matches!(version.as_str(),"2.0"|"3.0")||refs.is_empty()||refs.len()>200{return Err("Use an EPUB2/3 book with1–200 spine chapters".into())}
  let mut chapters=Vec::new();let mut paths=BTreeSet::new();for id in refs{let(p,m,props)=manifest.get(&id).ok_or("EPUB spine item missing")?;if m!="application/xhtml+xml"||props.split_whitespace().any(|p|matches!(p,"scripted"|"remote-resources"))||!paths.insert(p.clone())||!seen.contains(p){return Err("Unsupported or duplicated EPUB spine resource".into())}chapters.push(Chapter{path:p.clone(),title:format!("Chapter {}",chapters.len()+1)});}
  let nav=manifest.values().find(|(_,_,props)|props.split_whitespace().any(|p|p=="nav")).map(|(p,_,_)|(p.clone(),true)).or_else(||ncx.as_ref().and_then(|id|manifest.get(id)).map(|(p,_,_)|(p.clone(),false)));
  let mut toc=Vec::new();if let Some((navpath,is_nav))=nav{let events=xml::parse(&read(&mut zip,&navpath)?)?;let mut capture=false;let mut anchor:Option<(String,String)>=None;let mut label=String::new();let mut nav_depth=0usize;let mut point:Vec<(String,String,usize)>=Vec::new();let mut ordinal=0;
   for e in events{match e{
    Event::Open(n,a)=>{let tag=xml::local(&n);if is_nav{if tag=="nav"{nav_depth+=1;if xml::attr_local(&a,"type").is_some_and(|v|v.split_whitespace().any(|v|v=="toc")){capture=true}}if capture&&tag=="a"{anchor=xml::attr(&a,"href").map(|h|(h.into(),String::new()));}}else if tag=="navPoint"{point.push((String::new(),String::new(),ordinal));ordinal+=1;}else if tag=="content"{if let Some(p)=point.last_mut(){p.0=xml::attr(&a,"src").unwrap_or("").into();}}else if tag=="text"{label.clear();capture=true;}},
    Event::Text(t)=>{if is_nav{if let Some((_,label))=anchor.as_mut(){label.push_str(&t)}}else if capture{label.push_str(&t)}},
    Event::Close(n)=>{let tag=xml::local(&n);let link=if is_nav&&tag=="a"{anchor.take().map(|(h,l)|(h,l,0))}else if !is_nav&&tag=="text"{capture=false;if let Some(p)=point.last_mut(){p.1=label.trim().into()}None}else if !is_nav&&tag=="navPoint"{point.pop()}else{None};
     if let Some((href,label,order))=link{let(p,fragment)=path(&navpath,&href)?;let chapter=chapters.iter().position(|c|c.path==p).ok_or("TOC target is not in the spine")?;if toc.len()>=200{return Err("EPUB TOC exceeds200 entries".into())}let label=label.split_whitespace().collect::<Vec<_>>().join(" ").chars().take(256).collect::<String>();if !label.is_empty(){toc.push(json!({"title":label,"chapter":chapter,"anchor":fragment,"_order":order}));}}
     if is_nav&&tag=="nav"{nav_depth=nav_depth.saturating_sub(1);if nav_depth==0{capture=false}}
    }
   }}
  }
  toc.sort_by_key(|v|v["_order"].as_u64().unwrap_or(0));let mut titled=BTreeSet::new();for row in &mut toc{row.as_object_mut().unwrap().remove("_order");let index=row["chapter"].as_u64().unwrap()as usize;if titled.insert(index){chapters[index].title=row["title"].as_str().unwrap().into();}}
  if toc.is_empty(){return Err("Missing supported EPUB navigation table".into())}Ok(Self{zip,chapters,toc,author,title:if title.is_empty(){"Untitled book".into()}else{title},revision})
 }
 fn chapter(&mut self,index:usize)->Result<(String,BTreeMap<String,usize>)>{let c=self.chapters.get(index).ok_or("Chapter is out of range")?;let events=xml::parse(&read(&mut self.zip,&c.path)?)?;let mut text=String::new();let mut anchors=BTreeMap::new();let mut body=false;let mut seen_body=false;let mut hidden:usize=0;let mut pending_space=false;
  for e in events{match e{Event::Open(n,a)=>{let tag=xml::local(&n);if matches!(tag,"script"|"iframe"|"object"|"embed"){return Err("Active EPUB content is unsupported".into())}if tag=="body"{body=true;seen_body=true}if matches!(tag,"head"|"style"){hidden+=1}if body&&hidden==0{if matches!(tag,"p"|"div"|"section"|"article"|"h1"|"h2"|"h3"|"li"|"br"){if !text.is_empty()&&!text.ends_with('\n'){text.push('\n');}pending_space=false;}if let Some(id)=xml::attr_local(&a,"id"){if id.len()>256||anchors.len()>=1000||anchors.insert(id.into(),text.len()).is_some(){return Err("Duplicate or oversized EPUB anchor map".into())}}if tag=="img"{text.push_str(&format!("[Image: {}]",xml::attr(&a,"alt").unwrap_or("illustration not displayed")));}if tag=="svg"||tag=="math"{text.push_str("[Illustration/formula text follows]\n");}}},Event::Close(n)=>{let tag=xml::local(&n);if matches!(tag,"head"|"style"){hidden=hidden.saturating_sub(1)}if tag=="body"{body=false}if body&&hidden==0&&matches!(tag,"p"|"div"|"section"|"h1"|"h2"|"h3"|"li"){if !text.is_empty()&&!text.ends_with('\n'){text.push('\n')}pending_space=false;}},Event::Text(t)if body&&hidden==0=>{for c in t.chars(){if c.is_whitespace(){pending_space=true}else{if pending_space&&!text.is_empty()&&!text.ends_with('\n'){text.push(' ')}text.push(c);pending_space=false;}}},_=>{}}
   if text.len()>120_000{return Err("EPUB chapter text exceeds the120KiB text profile".into())}
  }if !seen_body{return Err("EPUB chapter has no XHTML body".into())}if serde_json::to_vec(&anchors).map_err(|_|"Invalid anchors")?.len()>16384{return Err("EPUB anchor map exceeds16KiB".into())}Ok((text,anchors))
 }
}
pub fn service(root:&Path,s:&str,a:&Value)->Result<Value>{
 let keys:&[&str]=match s{"epub.info"=>&["id"],"epub.chapter"=>&["id","chapter"],"epub.search"=>&["id","query","chapter","offset"],_=>return Err("Unsupported EPUB service".into())};let o=a.as_object().ok_or("Expected EPUB arguments")?;if o.len()!=keys.len()||o.keys().any(|k|!keys.contains(&k.as_str())){return Err("Unexpected EPUB arguments".into())}let id=a["id"].as_str().ok_or("Choose a private EPUB file")?;let mut book=Book::open(root,id)?;
 match s{
 "epub.info"=>{let info=json!({"id":id,"title":book.title,"author":book.author,"revision":book.revision,"chapters":book.chapters.iter().enumerate().map(|(index,c)|json!({"chapter":index,"title":c.title})).collect::<Vec<_>>(),"toc":book.toc,"profile":"offline-text-reflow"});if info.to_string().len()>64000{return Err("EPUB metadata exceeds64KiB".into())}Ok(info)},
 "epub.chapter"=>{let index=a["chapter"].as_u64().and_then(|n|usize::try_from(n).ok()).ok_or("Choose a chapter")?;let(text,anchors)=book.chapter(index)?;Ok(json!({"chapter":index,"title":book.chapters[index].title,"revision":book.revision,"text":text,"anchors":anchors}))},
 _=>{let query=a["query"].as_str().filter(|q|!q.is_empty()&&q.len()<=256).ok_or("Use a1–256-byte literal query")?;let start=a["chapter"].as_u64().and_then(|n|usize::try_from(n).ok()).filter(|n|*n<book.chapters.len()).ok_or("Invalid search chapter")?;let mut offset=a["offset"].as_u64().and_then(|n|usize::try_from(n).ok()).ok_or("Invalid search offset")?;let mut results=Vec::new();let mut consumed=0;let mut next=None;
  'chapters:for index in start..book.chapters.len(){let(text,_)=book.chapter(index)?;consumed+=text.len();if consumed>8_000_000{next=Some(json!({"chapter":index,"offset":0}));break}if !text.is_char_boundary(offset){return Err("Invalid Unicode search offset".into())}for(n,matched)in text[offset..].match_indices(query){let from=offset+n;let to=from+matched.len();results.push(json!({"chapter":index,"start":from,"end":to,"title":book.chapters[index].title}));if results.len()==40{next=if to<text.len(){Some(json!({"chapter":index,"offset":to}))}else if index+1<book.chapters.len(){Some(json!({"chapter":index+1,"offset":0}))}else{None};break 'chapters;}}offset=0;}
  Ok(json!({"items":results,"next":next,"revision":book.revision}))}
 }
}

#[cfg(test)]mod tests{
 use super::*;use std::io::Write;use zip::{ZipWriter,write::SimpleFileOptions};
 fn fixture()->Vec<u8>{include_bytes!("../../docs/fixtures/text-profile.epub").to_vec()}
 fn changed(name:&str,value:&str)->Vec<u8>{let mut original=ZipArchive::new(Cursor::new(fixture())).unwrap();let mut out=ZipWriter::new(Cursor::new(Vec::new()));for i in 0..original.len(){let mut f=original.by_index(i).unwrap();let mut bytes=Vec::new();f.read_to_end(&mut bytes).unwrap();let options=SimpleFileOptions::default().compression_method(if f.name()=="mimetype"{zip::CompressionMethod::Stored}else{zip::CompressionMethod::Deflated});out.start_file(f.name(),options).unwrap();out.write_all(if f.name()==name{value.as_bytes()}else{&bytes}).unwrap();}out.finish().unwrap().into_inner()}
 #[test]fn epub_spine_toc_anchors_and_safe_reflow_preserve_unicode(){let mut book=Book::bytes(fixture(),"rev".into()).unwrap();assert_eq!(book.title,"OnKlav sample book");assert_eq!(book.chapters.len(),2);assert_eq!(book.toc[1]["chapter"],1);assert_eq!(book.toc[1]["anchor"],"two");let(text,anchors)=book.chapter(0).unwrap();assert_eq!(text,"Chapter One\nAlpha 😀 needle.\n");assert_eq!(anchors["one"],0);let(text,_)=book.chapter(1).unwrap();assert!(text.contains("[Image: A sample cover]"));assert!(!text.contains("color:red"));}
 #[test]fn epub_private_search_and_foreign_handles_are_scoped(){let d=tempfile::tempdir().unwrap();let other=tempfile::tempdir().unwrap();let f=crate::sdk_storage::save_bytes(d.path(),"book.epub","application/epub+zip",&fixture()).unwrap();let id=f["id"].as_str().unwrap();let results=service(d.path(),"epub.search",&json!({"id":id,"query":"needle","chapter":0,"offset":0})).unwrap();assert_eq!(results["items"].as_array().unwrap().len(),2);assert_eq!(results["items"][1]["chapter"],1);assert!(results["next"].is_null());assert!(service(other.path(),"epub.info",&json!({"id":id})).is_err());assert!(service(d.path(),"epub.info",&json!({"id":id,"path":"foreign"})).is_err());assert!(service(d.path(),"epub.search",&json!({"id":id,"query":"x","chapter":0,"offset":20})).is_err());}
 #[test]fn epub_rejects_traversal_external_entities_and_active_content(){assert!(path("Book/book.opf","../../outside.xhtml").is_err());assert!(path("Book/book.opf","%2e%2e/%2e%2e/outside.xhtml").is_err());assert!(path("Book/book.opf","https://remote/x").is_err());assert_eq!(path("Book/book.opf","../Text/chapter.xhtml#hello").unwrap(),("Text/chapter.xhtml".into(),"hello".into()));let bad=changed("Book/one.xhtml","<!DOCTYPE html [<!ENTITY x SYSTEM 'file:///secret'>]><html><body>&x;</body></html>");assert!(Book::bytes(bad,"r".into()).unwrap().chapter(0).is_err());let script=changed("Book/one.xhtml","<html><body><script>bad()</script></body></html>");assert!(Book::bytes(script,"r".into()).unwrap().chapter(0).is_err());}
 #[test]fn epub_fixed_layout_duplicates_and_missing_navigation_fail_closed(){let mut original=ZipArchive::new(Cursor::new(fixture())).unwrap();let opf=read(&mut original,"Book/book.opf").unwrap();let fixed=opf.replace("<metadata ","<metadata ").replace("</metadata>","<meta property=\"rendition:layout\">pre-paginated</meta></metadata>");assert!(Book::bytes(changed("Book/book.opf",&fixed),"r".into()).is_err());assert!(Book::bytes(changed("Book/nav.xhtml","<html><body>no table</body></html>"),"r".into()).is_err());let duplicate=opf.replace("<itemref idref=\"two\"/>","<itemref idref=\"one\"/>");assert!(Book::bytes(changed("Book/book.opf",&duplicate),"r".into()).is_err());assert!(Book::bytes(changed("mimetype","wrong"),"r".into()).is_err());}
 #[test]fn epub_xml_limits_and_malformed_documents_never_resolve_entities(){for s in ["<a><b></a>","<a x='1' x='2'/>","<a>&unknown;</a>","<a>&#0;</a>","<a/><b/>","<!ENTITY x 'y'><a/>"]{assert!(xml::parse(s).is_err(),"{s}");}assert!(xml::parse(&format!("{}{}","<a>".repeat(70),"</a>".repeat(70))).is_err());assert!(xml::parse("<a>😀 &amp; &#x1f600; <![CDATA[raw <x>]]></a>").is_ok());}
}

#[cfg(test)]mod additional_tests{
 use super::*;use std::io::Write;use zip::{ZipWriter,write::SimpleFileOptions};
 fn rewrite(opf:String,nav:String,extra:Option<(&str,Vec<u8>)>)->Vec<u8>{let mut z=ZipArchive::new(Cursor::new(include_bytes!("../../docs/fixtures/text-profile.epub").to_vec())).unwrap();let mut out=ZipWriter::new(Cursor::new(Vec::new()));for i in 0..z.len(){let mut f=z.by_index(i).unwrap();let mut bytes=Vec::new();f.read_to_end(&mut bytes).unwrap();out.start_file(f.name(),SimpleFileOptions::default().compression_method(f.compression())).unwrap();out.write_all(if f.name()=="Book/book.opf"{opf.as_bytes()}else if f.name()=="Book/nav.xhtml"{nav.as_bytes()}else{&bytes}).unwrap();}if let Some((name,data))=extra{out.start_file(name,SimpleFileOptions::default()).unwrap();out.write_all(&data).unwrap();}out.finish().unwrap().into_inner()}
 fn source()->(String,String){let mut z=ZipArchive::new(Cursor::new(include_bytes!("../../docs/fixtures/text-profile.epub").to_vec())).unwrap();(read(&mut z,"Book/book.opf").unwrap(),read(&mut z,"Book/nav.xhtml").unwrap())}
 #[test]fn epub2_nested_ncx_keeps_parent_before_child_and_supports_external_doctype_without_fetch(){let(opf,_)=source();let opf=opf.replace("version=\"3.0\"","version=\"2.0\"").replace("href=\"nav.xhtml\" media-type=\"application/xhtml+xml\" properties=\"nav\"","href=\"nav.xhtml\" media-type=\"application/x-dtbncx+xml\"").replace("<spine>","<spine toc=\"nav\">");let nav="<!DOCTYPE ncx PUBLIC '-//NISO//DTD ncx 2005-1//EN' 'http://www.daisy.org/z3986/2005/ncx-2005-1.dtd'><ncx><navMap><navPoint><navLabel><text>First</text></navLabel><content src='one.xhtml#one'/><navPoint><navLabel><text>Second</text></navLabel><content src='two.xhtml#two'/></navPoint></navPoint></navMap></ncx>";let book=Book::bytes(rewrite(opf,nav.into(),None),"r".into()).unwrap();assert_eq!(book.toc[0]["title"],"First");assert_eq!(book.toc[1]["title"],"Second");}
 #[test]fn epub_drm_and_archive_traversal_are_rejected_before_content_read(){let(opf,nav)=source();assert!(Book::bytes(rewrite(opf.clone(),nav.clone(),Some(("META-INF/encryption.xml",b"encrypted".to_vec()))),"r".into()).is_err());assert!(Book::bytes(rewrite(opf,nav,Some(("../outside",b"bad".to_vec()))),"r".into()).is_err());}
}
#[cfg(test)]mod large_book_tests{use super::*;use std::io::Write;use zip::{ZipWriter,write::SimpleFileOptions};
 #[test]fn illustrated_book_over_old_download_and_library_limits_reads_from_disk(){let d=tempfile::tempdir().unwrap();let root=d.path().join("app.onklav.ebooks");std::fs::create_dir(&root).unwrap();assert_eq!(crate::sdk_storage::limits(&root).unwrap().files,ZIP_MAX);let made=crate::sdk_storage::service(&root,"blobs.begin",&json!({"name":"Large.epub","mime":"application/epub+zip"})).unwrap();let id=made["id"].as_str().unwrap();let file=File::create(root.join("private-blobs-v1").join(format!("{id}.data"))).unwrap();let mut writer=ZipWriter::new(file);let mut source=ZipArchive::new(Cursor::new(include_bytes!("../../docs/fixtures/text-profile.epub"))).unwrap();for i in 0..source.len(){let mut part=source.by_index(i).unwrap();writer.start_file(part.name(),SimpleFileOptions::default().compression_method(part.compression())).unwrap();std::io::copy(&mut part,&mut writer).unwrap();}writer.start_file("Images/large.jpg",SimpleFileOptions::default().compression_method(zip::CompressionMethod::Stored)).unwrap();for _ in 0..65*128{writer.write_all(&[37;8192]).unwrap();}writer.finish().unwrap();let saved=crate::sdk_storage::service(&root,"blobs.finish",&json!({"id":id})).unwrap();assert!(saved["size"].as_u64().unwrap()>64*1024*1024);assert_eq!(service(&root,"epub.info",&json!({"id":id})).unwrap()["title"],"OnKlav sample book");assert!(service(&root,"epub.chapter",&json!({"id":id,"chapter":0})).unwrap()["text"].as_str().unwrap().contains("Alpha"));crate::sdk_storage::admin(&root,&json!({"operation":"limits","documents":16*1024*1024,"files":128*1024*1024,"cache":0})).unwrap();assert_eq!(crate::sdk_storage::limits(&root).unwrap().files,128*1024*1024);}
}
